// Count Vowels
// Подсчитай гласные в строке

function countVowels(s) {
  // TODO: implement
  return 0;
}

solution:
function countVowels(s) {
  let n = 0;
  for (const c of s.toLowerCase()) {
    if ('aeiou'.includes(c)) n += 1;
  }
  return n;
}

