// Capitalize Words
// Первая буква каждого слова — заглавная

function capitalize(s) {
  // TODO: implement
  return s;
}

solution:
function capitalize(s) {
  return s.split(' ').map((w) => (w ? w[0].toUpperCase() + w.slice(1) : w)).join(' ');
}

