// FizzBuzz
// 1..n: кратные 3 → Fizz, 5 → Buzz, обоим → FizzBuzz

function fizzBuzz(n) {
  // TODO: implement
  return [];
}

solution:
function fizzBuzz(n) {
  const out = [];
  for (let i = 1; i <= n; i++) {
    out.push(i % 15 === 0 ? 'FizzBuzz' : i % 3 === 0 ? 'Fizz' : i % 5 === 0 ? 'Buzz' : String(i));
  }
  return out;
}

