// Flatten a Nested Array
// Рекурсивно разверни вложенный массив

function flatten(arr) {
  // TODO: implement
  return arr;
}

solution:
function flatten(arr) {
  const out = [];
  for (const v of arr) {
    if (Array.isArray(v)) out.push(...flatten(v));
    else out.push(v);
  }
  return out;
}

