// Палиндром без учёта регистра и пунктуации

function isPalindrome(s) {
  // TODO: implement
  return false;
}

solution:
function isPalindrome(s) {
  const t = s.replace(/[^a-z0-9]/gi, '').toLowerCase();
  return t === t.split('').reverse().join('');
}

