// Binary Search
// Двоичный поиск: индекс target или -1

function binarySearch(arr, target) {
  // TODO: implement (logarithmic complexity)
  return -1;
}

solution:
function binarySearch(arr, target) {
  let lo = 0, hi = arr.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (arr[mid] === target) return mid;
    if (arr[mid] < target) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}

